#include <iostream>
#include <vector>
#include <algorithm>
void merge_sort(std::vector<int>&a,std::size_t lo,std::size_t hi,int depth,int&maximum){
 maximum=std::max(maximum,depth);
 if(hi-lo<2)return;
 const auto mid=lo+(hi-lo)/2;
 merge_sort(a,lo,mid,depth+1,maximum);merge_sort(a,mid,hi,depth+1,maximum);
 std::vector<int>tmp;auto i=lo,j=mid;
 while(i<mid&&j<hi){if(a[j]<a[i])tmp.push_back(a[j++]);else tmp.push_back(a[i++]);}
 while(i<mid)tmp.push_back(a[i++]);while(j<hi)tmp.push_back(a[j++]);
 std::copy(tmp.begin(),tmp.end(),a.begin()+static_cast<std::ptrdiff_t>(lo));
}
int main(){int n;if(!(std::cin>>n)||n<0||n>128){std::cout<<"invalid\n";return 0;}
 std::vector<int>a;for(int i=0;i<n;++i){int x;if(!(std::cin>>x)||x< -10000||x>10000){std::cout<<"invalid\n";return 0;}a.push_back(x);}
 std::cin>>std::ws;if(!std::cin.eof()){std::cout<<"invalid\n";return 0;}
 int maximum=0;merge_sort(a,0,a.size(),1,maximum);
 for(std::size_t i=0;i<a.size();++i){if(i)std::cout<<' ';std::cout<<a[i];}std::cout<<"\nmax-depth "<<maximum<<'\n';
}
